47	        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
48	        int terms = terms(person, settings);
49	        LocalDate dueBy = holidays.businessDaysAfter(person.sheetId(), date, terms);
50	        if (periods.closedOn(person.sheetId(), dueBy)) {
51	            throw new InvalidClaimException("The claim's due-by is inside a closed period");
52	        }
