61	     *  claim being edited (null for an add), whose own reference does not count. */
62	    public static void checkRef(String sheetId, ClaimValues values, Long self, ClaimRepository claims) throws InvalidClaimException {
63	        if (values.ref() != null && claims.refUsed(sheetId, values.ref(), self)) {
64	            throw new InvalidClaimException("The reference " + values.ref() + " is already used on the sheet");
