109	public final class ClaimDue {
110	
111	    private ClaimDue() {
112	    }
113	
114	    /** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do. */
115	    public static boolean counts(Claim claim) {
116	        return isOpen(claim) || claim.status() == ClaimStatus.SETTLED;
117	    }
118	
119	    /** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim). */
120	    public static boolean isOpen(Claim claim) {
121	        return claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING;
122	    }
123	
124	    /** Whether a claim counts toward the live totals (claimed, due-totals, a period's due-total): one that counts. A
125	     *  hold (the claim's or its person's) does not take it out; a hold only takes a person's cut in the pools. */
126	    public static boolean countsLive(Claim claim, net.officefloor.hq.app.person.Person person) {
127	        return counts(claim);
128	    }
129	
130	    /** Whether a claim is deferred on the given today: a claim that counts, deferred until a date after it, and not
131	     *  bound by a statement. Until then it counts in no total, is not overdue, cannot be settled and is left unbound
132	     *  by a statement; from that day on it is a claim like any other. A claim deferred while a statement binds it
133	     *  stays in the totals, counts and can be settled while bound: the deferral takes effect only once the binding
134	     *  ends (the statement is cancelled, or the next statement leaves it unbound). */
135	    public static boolean deferred(Claim claim, java.time.LocalDate today) {
136	        return counts(claim) && !bound(claim) && claim.deferredUntil() != null
137	                && claim.deferredUntil().isAfter(today);
138	    }
139	
140	    /** Whether a claim counts toward the live totals on the given today: as {@link #countsLive(Claim,
141	     *  net.officefloor.hq.app.person.Person)}, unless it is deferred, or it is open, not bound by a statement, and its
142	     *  person's retirement date is reached on today. */
143	    public static boolean countsLive(Claim claim, net.officefloor.hq.app.person.Person person,
144	            java.time.LocalDate today) {
145	        return countsLive(claim, person) && !deferred(claim, today) && !retiredOut(claim, person, today);
146	    }
147	
148	    /** Whether a claim counts toward claimed (a person's claimed, the claimed-total) on the given today: as {@link
149	     *  #countsLive(Claim, net.officefloor.hq.app.person.Person, java.time.LocalDate)}, which it now matches. */
150	    public static boolean countsClaimed(Claim claim, net.officefloor.hq.app.person.Person person,
151	            java.time.LocalDate today) {
152	        return counts(claim) && !deferred(claim, today) && !retiredOut(claim, person, today);
153	    }
154	
155	    /** Whether a claim leaves the live totals for its person's retirement: it is open (OPEN or PENDING), not bound by
156	     *  a statement, and its person's retirement date is on or before today (null person: never). */
157	    public static boolean retiredOut(Claim claim, net.officefloor.hq.app.person.Person person,
158	            java.time.LocalDate today) {
159	        return isOpen(claim) && !bound(claim) && person != null && person.retiredOn(today);
160	    }
161	
162	    /** The claim's rate figure: its amount at the grade's rate that applies to it on its date (a forward-only rate
163	     *  saved after it was added does not; see RateRepository#forClaim), rounded to two decimals by the
164	     *  claim's rounding (see Rounding); null when no rate applies. The floor is applied to it before the late charge
165	     *  (see LateCharge#add). */
166	    public static BigDecimal live(Claim claim, String grade, RateRepository rates, Rounding rounding) {
167	        Rate rate = rates.forClaim(claim.sheetId(), grade, claim.date(), rates.seqOf(claim.id()));
168	        if (rate == null) {
169	            return null;
170	        }
171	        return claim.amount().multiply(rate.rate()).movePointLeft(2).setScale(2, rounding.mode(claim));
172	    }
173	
174	    /** Whether the claim is a correction: its amount is negative. */
175	    public static boolean isCorrection(Claim claim) {
176	        return claim.amount().signum() < 0;
177	    }
178	
179	    /** The figure the claim shows: fixed when settled, else the one a statement bound it to (PENDING included),
180	     *  else its live rate figure; null when it has none (n/a). */
181	    public static BigDecimal figure(Claim claim, String grade, RateRepository rates, Rounding rounding) {
182	        if (claim.due() != null) {
183	            return claim.due();
184	        }
185	        return bound(claim) ? claim.statedDue() : live(claim, grade, rates, rounding);
186	    }
187	
188	    /** Whether the claim keeps a figure whatever the rates are: fixed when settled, or bound by a statement. */
189	    public static boolean kept(Claim claim) {
190	        return claim.due() != null || (bound(claim) && claim.statedDue() != null);
191	    }
192	
193	    /** Whether a statement binds the claim now: it is stated (PENDING included, like any claim that counts). */
194	    public static boolean bound(Claim claim) {
195	        return claim.stated();
196	    }
197	
198	    /** The status a claim had at the end of a day, as its status log (oldest first) records it: that of the last line
199	     *  made on or before the day; null when the claim was added after it. */
200	    public static ClaimStatus statusAsOf(java.util.List<ClaimLogLine> log, java.time.LocalDate day) {
201	        ClaimStatus status = null;
202	        for (ClaimLogLine line : log) {
203	            if (!line.date().isAfter(day)) {
204	                status = line.status();
205	            }
206	        }
207	        return status;
208	    }
209	
210	    /** The claim as it would be with another status, all else kept. */
211	    public static Claim withStatus(Claim c, ClaimStatus status) {
212	        return new Claim(c.id(), c.sheetId(), c.personId(), c.amount(), c.date(), c.note(), status, c.number(), c.due(),
213	                c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(), c.proofs(), c.splitFrom(), c.ref(), c.tags(), c.held());
214	    }
