245	    public static Figure of(Claim claim, LocalDate date, ClaimRepository claims, ClaimLogRepository log,
246	            PersonRepository people, RateRepository rates, SettingRepository settings, StatementRepository statements)
247	            throws InvalidClaimStatusException {
248	        String sheetId = claim.sheetId();
249	        List<ClaimLogLine> lines = log.of(sheetId, claim.id());
250	        ClaimStatus status = lines.isEmpty() ? claim.status() : ClaimDue.statusAsOf(lines, date);
251	        if (status == null) {
252	            throw new InvalidClaimStatusException("The claim was not on the sheet on " + date);
253	        }
254	        Person current = people.find(sheetId, claim.personId());
255	        Person person = current == null ? null : people.asOf(current, date);
256	        SheetAsOf sheet = SheetAsOf.read(sheetId, date, rates, settings);
257	        LocalDate policy = sheet.policyDate();
258	        Rounding rounding = new Rounding(policy == null ? date : policy, claims,
259	                (on) -> sheet.value(SettingRepository.ROUNDING, on));
260	        LateCharge late = new LateCharge(date, sheet::latePct, rounding,
261	                (c) -> sheet.grace(person == null ? null : person.gradeOn(c.date()), c.date()),
262	                LateCharge.waivedIn(claims.waived(sheetId, date)));
263	        Claim values = claims.editedAfter(sheetId, date).getOrDefault(claim.id(), claim);
264	        var deferred = claims.deferredAsOf(sheetId, date);
265	        Statement last = claim.stated() ? statements.last(sheetId, claim.personId()) : null;
266	        boolean stated = last != null && AsOf.counts(last.madeOn(), date);
267	        Claim then = new Claim(claim.id(), sheetId, claim.personId(), values.amount(), values.date(), values.note(),
268	                status, claim.number(), status == ClaimStatus.SETTLED ? claim.due() : null, claim.openedBy(), stated,
269	                stated ? claim.statedDue() : null, values.corrects(), claim.dueBy(),
270	                deferred.containsKey(claim.id()) ? deferred.get(claim.id()) : claim.deferredUntil(), claim.proofs(),
271	                claim.splitFrom(), values.ref(), values.tags(), claim.held());
272	        if (person == null) {
273	            return new Figure(then.due());
274	        }
275	        return new Figure(late.add(then, figure(then, person.gradeOn(then.date()), sheet, rounding, rates),
276	                sheet.floor(then.date())));
277	    }
