308	 * How a claim's live figures (the rate step and the late charge) are rounded to two decimals: a claim dated before
309	 * the sheet's policy date (its today while the policy date is blank) rounds half up, one dated on or after it half to
310	 * even; unless a rounding mode (the dated setting rounding, half-up or half-even) is in force on its date, when it rounds
311	 * by that mode. A correction rounds by the date of the claim it corrects, not its own.
312	 */
313	public record Rounding(LocalDate policy, ClaimRepository claims, Function<LocalDate, String> modeOn) {
314	
315	    public static Rounding of(String sheetId, SheetRepository sheets, SettingRepository settings, ClaimRepository claims) {
316	        LocalDate policy = settings.policyDate(sheetId);
317	        return new Rounding(policy == null ? sheets.today(sheetId) : policy, claims,
318	                (date) -> settings.value(sheetId, SettingRepository.ROUNDING, date));
319	    }
320	
321	    /** The date that decides how the claim rounds: the corrected claim's date for a correction, else its own. */
322	    public static LocalDate roundsOn(Claim claim, ClaimRepository claims) {
323	        if (claim.corrects() != null) {
324	            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
325	            if (corrected != null) {
326	                return corrected.date();
327	            }
328	        }
329	        return claim.date();
330	    }
331	
332	    /** The rounding the claim's live figures take. */
333	    public RoundingMode mode(Claim claim) {
334	        LocalDate on = roundsOn(claim, claims);
335	        String mode = modeOn.apply(on);
336	        if (SettingRepository.HALF_UP.equals(mode)) {
337	            return RoundingMode.HALF_UP;
338	        }
339	        if (SettingRepository.HALF_EVEN.equals(mode)) {
340	            return RoundingMode.HALF_EVEN;
341	        }
342	        return on.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
