392	        if (figure == null || !ClaimDue.isOpen(claim) || claim.due() != null || ClaimDue.isCorrection(claim)
393	                || ClaimDue.deferred(claim, today) || waived.test(claim)) {
394	            return BigDecimal.ZERO.setScale(2);
