436	    /** The number the claim with these values corrects (null when it is not a correction); a correction that does
437	     *  not name a SETTLED claim of the person is refused. */
438	    public static String check(String sheetId, long personId, ClaimValues values, ClaimRepository claims)
439	            throws InvalidClaimException {
440	        return check(sheetId, personId, values, null, claims);
441	    }
442	
443	    /** As check, for the claim {@code self} being edited (null for an add), whose own amount does not count against
444	     *  what remains of the claim it corrects; a correction larger than what remains is refused. */
445	    public static String check(String sheetId, long personId, ClaimValues values, Long self, ClaimRepository claims)
446	            throws InvalidClaimException {
447	        if (values.amount().signum() >= 0) {
448	            return null;
449	        }
450	        if (values.corrects() == null) {
451	            throw new InvalidClaimException("A negative amount must name the settled claim it corrects");
452	        }
453	        Claim corrected = claims.findByNumber(sheetId, personId, values.corrects());
454	        if (corrected == null || corrected.status() != ClaimStatus.SETTLED) {
455	            throw new InvalidClaimException("A correction must name a settled claim of the same person");
456	        }
457	        if (remaining(corrected, self, claims).add(values.amount()).signum() < 0) {
458	            throw new InvalidClaimException("A correction may not exceed what remains of the claim it corrects");
459	        }
460	        return values.corrects();
461	    }
462	
463	    /** The claim's amount less the amounts of the corrections made against it (VOID or DELETED ones, and {@code self},
464	     *  left out). */
465	    private static BigDecimal remaining(Claim corrected, Long self, ClaimRepository claims) {
466	        BigDecimal remaining = corrected.amount();
467	        for (Claim c : claims.list(corrected.sheetId())) {
468	            if (c.personId() == corrected.personId() && corrected.number().equals(c.corrects())
469	                    && c.status() != ClaimStatus.VOID && c.status() != ClaimStatus.DELETED
470	                    && (self == null || c.id() != self)) {
471	                remaining = remaining.add(c.amount());
472	            }
473	        }
474	        return remaining;
475	    }
476	}
