package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimDue;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimShare;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed (the amounts of their claims that count added up, leaving out corrections; a person's OPEN or PENDING claims, once their retirement date is reached, not bound by a statement, do not, nor do deferred claims; a held claim still does) and
 * due-total (the figures of the claims that count live — held ones included, each with its late charge, added up, less
 * the parts of them other people hold by a share, plus their own parts of others' shared claims (see ClaimShare#part, at their own grade's rate); n/a when their grade has no rate today and no counting claim
 * has a figure, kept or at the grade in force on its date; at most the sheet's cap less their cut total, not below 0.00), overdue-total (the figures, late charge included, of those claims that are overdue — open, their due-by plus
 * their grace (see LateCharge#lateFrom) before today — added up, skipping n/a; not capped), and the sheet's claimed-total, due-total and overdue-total (everyone's added up, skipping n/a; the due-total and
 * overdue-total leave out the single highest and the single lowest figure when three or more people have one).
 *
 * A change takes the figures before it ({@link #take}) and, after its own audit lines, writes ROLLUP for every
 * person whose figures (claimed, due-total or overdue-total) moved (a person new to the sheet counts as moved), then
 * TOTALS when any of the sheet's three totals moved ({@link #record}), then ALERT, in list order, for every person
 * whose due-total went from at or below the sheet's alert threshold (or no due-total: n/a, or new to the sheet) to
 * above it (none while the threshold is off).
 */
@Service
public class Rollup {

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;
    private final PoolRepository pools;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, PoolRepository pools, Audit audit) {
        this.pools = pools;
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** Every person's figures on the sheet now, in list order (see PersonRepository#list). */
    public RollupBefore take(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        LateCharge late = LateCharge.of(sheetId, sheets, settings, claims);
        List<Claim> all = claims.list(sheetId);
        List<Person> listed = people.list(sheetId);
        Map<Long, BigDecimal> parts = shareParts(sheetId, today, late, all, listed);
        Map<Long, BigDecimal> cuts = pools.cutTotals(sheetId, null);
        Map<Long, Figures> figures = new LinkedHashMap<>();
        for (Person person : listed) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            BigDecimal settled = BigDecimal.ZERO.setScale(2);
            int overdueCount = 0;
            boolean figured = false;
            LocalDate latest = null;
            for (Claim c : all) {
                if (c.personId() != person.id()) {
                    continue;
                }
                if (c.corrects() == null && ClaimDue.countsClaimed(c, person, today)) {
                    claimed = claimed.add(c.amount());
                }
                if (!ClaimDue.countsLive(c, person, today)) {
                    continue;
                }
                if (latest == null || c.date().isAfter(latest)) {
                    latest = c.date();
                }
                BigDecimal figure = late.add(c, ClaimDue.figure(c, person.gradeOn(c.date()), rates, late.rounding()), settings.floor(sheetId, c.date()));
                figured |= figure != null;
                boolean overdueNow = ClaimDue.isOpen(c) && late.lateFrom(c).isBefore(today);
                if (overdueNow) {
                    overdueCount++;
                }
                if (figure != null && c.status() == ClaimStatus.SETTLED && c.corrects() == null) {
                    settled = settled.add(figure);
                }
                if (figure != null) {
                    due = due.add(figure);
                    if (overdueNow) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            BigDecimal part = parts.get(person.id());
            if (part != null) {
                due = due.add(part);
                figured = true;
            }
            String dueTotal = rates.find(sheetId, person.gradeOn(today), today) == null && !figured ? "n/a"
                    : SettingRepository.capped(due, settings.cap(sheetId, latest == null ? today : latest), cuts.get(person.id())).toPlainString();
            figures.put(person.id(), new Figures(person.name(), claimed.toPlainString(), dueTotal,
                    overdue.toPlainString(), score(settled, overdueCount)));
        }
        return new RollupBefore(figures);
    }

    /** What the shares of the sheet's claims that count live move in each person's due-total now (see #shareParts), by
     *  person id. */
    public Map<Long, BigDecimal> shareParts(String sheetId) {
        return shareParts(sheetId, sheets.today(sheetId), LateCharge.of(sheetId, sheets, settings, claims),
                claims.list(sheetId), people.list(sheetId));
    }

    /** What the shares of the claims that count live move in each person's due-total, by person id: each holder gains
     *  their part of the claim (see ClaimShare#part: at their own grade's rate; frozen with the due once settled), and
     *  the claim's own person loses it. A person with no
     *  share of a claim that has a figure is left out. */
    private Map<Long, BigDecimal> shareParts(String sheetId, LocalDate today, LateCharge late, List<Claim> all,
            List<Person> listed) {
        Map<Long, List<ClaimShare>> shares = claims.shares(sheetId, (LocalDate) null);
        Map<Long, BigDecimal> parts = new HashMap<>();
        if (shares.isEmpty()) {
            return parts;
        }
        Map<Long, Person> byId = new HashMap<>();
        listed.forEach((p) -> byId.put(p.id(), p));
        for (Claim c : all) {
            List<ClaimShare> held = shares.get(c.id());
            Person owner = byId.get(c.personId());
            if (held == null || owner == null || !ClaimDue.countsLive(c, owner, today)) {
                continue;
            }
            BigDecimal figure = late.add(c, ClaimDue.figure(c, owner.gradeOn(c.date()), rates, late.rounding()), settings.floor(sheetId, c.date()));
            if (figure == null) {
                continue;
            }
            for (ClaimShare s : held) {
                BigDecimal part;
                if (c.due() != null) {
                    part = s.part(figure);
                } else {
                    Person holder = byId.get(s.personId());
                    net.officefloor.hq.app.rate.Rate rate = holder == null ? null
                            : rates.forClaim(sheetId, holder.gradeOn(c.date()), c.date(), rates.seqOf(c.id()));
                    if (rate == null) {
                        continue; // a 0.00 part: it leaves the holder's figures as they were
                    }
                    part = s.part(c.amount(), rate.rate(), late.rounding().mode(c));
                }
                parts.merge(s.personId(), part, BigDecimal::add);
                parts.merge(owner.id(), part.negate(), BigDecimal::add);
            }
        }
        return parts;
    }

    /** A score from settled figures and an overdue count: settled / 100, minus 5 for every overdue claim, rounded once,
     *  half to even, to a whole number. */
    private static String score(BigDecimal settled, int overdueCount) {
        return settled.movePointLeft(2).subtract(BigDecimal.valueOf(5L * overdueCount))
                .setScale(0, java.math.RoundingMode.HALF_EVEN).toPlainString();
    }

    /** Writes the ROLLUP and TOTALS lines for the figures the change moved since {@code before}. */
    public void record(String sheetId, String by, RollupBefore before) {
        lines(sheetId, by, before).forEach(audit::record);
    }

    /** The ROLLUP, TOTALS and ALERT lines {@link #record} would write, without writing them (for a change that writes
     *  its lines only once all of it has gone through). */
    public List<String> lines(String sheetId, String by, RollupBefore before) {
        List<String> lines = new ArrayList<>();
        Map<Long, Figures> after = take(sheetId).figures();
        for (Map.Entry<Long, Figures> e : after.entrySet()) {
            Figures was = before.figures().get(e.getKey());
            Figures now = e.getValue();
            if (was == null || !was.claimed().equals(now.claimed()) || !was.dueTotal().equals(now.dueTotal())
                    || !was.overdueTotal().equals(now.overdueTotal())) {
                lines.add("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + now.name() + " claimed="
                        + now.claimed() + " due-total=" + now.dueTotal() + " overdue-total=" + now.overdueTotal());
            }
        }
        String claimedBefore = claimedTotal(before.figures());
        String dueBefore = dueTotal(before.figures());
        String claimedAfter = claimedTotal(after);
        String dueAfter = dueTotal(after);
        String overdueBefore = overdueTotal(before.figures());
        String overdueAfter = overdueTotal(after);
        if (!Objects.equals(claimedBefore, claimedAfter) || !Objects.equals(dueBefore, dueAfter)
                || !Objects.equals(overdueBefore, overdueAfter)) {
            lines.add("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedAfter + " due-total="
                    + dueAfter + " overdue-total=" + overdueAfter);
        }
        alert(sheetId, by, before.figures(), after, lines);
        return lines;
    }

    /** Writes ALERT, in list order, for every person whose due-total went from at or below the sheet's alert threshold
     *  (or no due-total) before to above it now. */
    private void alert(String sheetId, String by, Map<Long, Figures> before, Map<Long, Figures> after, List<String> lines) {
        BigDecimal threshold = settings.alertThreshold(sheetId);
        if (threshold == null) {
            return;
        }
        for (Map.Entry<Long, Figures> e : after.entrySet()) {
            Figures was = before.get(e.getKey());
            Figures now = e.getValue();
            if (above(now, threshold) && (was == null || !above(was, threshold))) {
                lines.add("ALERT sheet=" + sheetId + " by=" + by + " name=" + now.name() + " due-total="
                        + now.dueTotal());
            }
        }
    }

    private static boolean above(Figures figures, BigDecimal threshold) {
        return !figures.dueTotal().equals("n/a") && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
    }

    /** Writes ROLLUP for every person on the sheet, in list order, then TOTALS, then ALERT for those above the alert
     *  threshold: the figures of a sheet just made. */
    public void recordAll(String sheetId, String by) {
        Map<Long, Figures> now = take(sheetId).figures();
        for (Figures f : now.values()) {
            audit.record("ROLLUP sheet=" + sheetId + " by=" + by + " person=" + f.name() + " claimed=" + f.claimed()
                    + " due-total=" + f.dueTotal() + " overdue-total=" + f.overdueTotal());
        }
        audit.record("TOTALS sheet=" + sheetId + " by=" + by + " claimed-total=" + claimedTotal(now) + " due-total="
                + dueTotal(now) + " overdue-total=" + overdueTotal(now));
        List<String> alerts = new ArrayList<>();
        alert(sheetId, by, Map.of(), now, alerts);
        alerts.forEach(audit::record);
    }

    private static String claimedTotal(Map<Long, Figures> figures) {
        return figures.values().stream().map((f) -> new BigDecimal(f.claimed()))
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    }

    private static String overdueTotal(Map<Long, Figures> figures) {
        return trimmedTotal(figures.values().stream().map(Figures::overdueTotal).toList());
    }

    private static String dueTotal(Map<Long, Figures> figures) {
        return trimmedTotal(figures.values().stream().map(Figures::dueTotal).toList());
    }

    /** The figures added up, skipping n/a, leaving out the single highest and the single lowest when three or more are left. */
    private static String trimmedTotal(List<String> values) {
        List<BigDecimal> figures = values.stream().filter((v) -> !v.equals("n/a")).map(BigDecimal::new).sorted().toList();
        if (figures.size() >= 3) {
            figures = figures.subList(1, figures.size() - 1);
        }
        return figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person on a sheet: a name (unique on the sheet, case ignored; kept without surrounding spaces) and a grade, one of A, B or C.
 *  The grade is dated: {@code grades} are the grades recorded, by from-date (the one with none, the first given, first), and
 *  {@code grade} is the one in force on the sheet's today.
 *  The version is 0 when added and goes up by one on each stored edit. {@code retiredFrom} (yyyy-MM-dd) is the date the
 *  person is retired from, null when not retired; a person with one counts as retired at once, whatever the date.
 *  {@code holds} are the person's holds, by from-date: an OPEN or PENDING claim of theirs dated within one, and not bound by
 *  a statement, counts in no live total. {@code held} is whether they have any hold. {@code terms} are the person's own
 *  terms (days a claim of theirs has until it is due by, ahead of their grade's and the sheet's) in force on the sheet's
 *  today, null when none; {@code ownTerms} are their own terms as recorded, by from-date (the one from the beginning of
 *  time, with none, first), a claim having those in force on its date. {@code contact} is the person's contact (unique on the sheet; kept without
 *  surrounding spaces, lower-cased), null when none. {@code aliases} are the person's aliases, sorted as names are compared
 *  (each kept without surrounding spaces; no alias equals, case ignored, any name or alias on the sheet). {@code clashing}
 *  is whether their name or an alias is used as a name or alias on another sheet of the sheet's tree (see
 *  PersonRepository#treeKeys): set only on the people listed, false elsewhere. {@code origin} is the sheet the person was
 *  last transferred from, null when they were never transferred here. {@code retirements} are the person's past
 *  retirements (each ended by unretiring them), in the order they ended. {@code tags} are the person's tags (each trimmed and
 *  in lower case, no repeats, sorted; empty when none): a claim of theirs counts for each in the tag totals. {@code flag} is the
 *  reason and until-date a steward last flagged them with, null when never flagged: while the sheet's today is on or before its
 *  until-date only a steward may open a claim of theirs (see PersonFlag). */
public record Person(long id, String sheetId, String name, String grade, long version, String retiredFrom, boolean held,
        List<PersonGrade> grades, List<PersonHold> holds, Integer terms, String contact, List<String> aliases,
        boolean clashing, String origin, List<PersonRetirement> retirements, List<String> tags, List<PersonTerms> ownTerms,
        PersonFlag flag) {

    public Person(long id, String sheetId, String name, String grade, long version, String retiredFrom, boolean held,
            List<PersonGrade> grades, List<PersonHold> holds, Integer terms, String contact, List<String> aliases,
            boolean clashing, String origin, List<PersonRetirement> retirements, List<String> tags, List<PersonTerms> ownTerms) {
        this(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin,
                retirements, tags, ownTerms, null);
    }

    public Person(long id, String sheetId, String name, String grade, long version, String retiredFrom, boolean held,
            List<PersonGrade> grades, List<PersonHold> holds, Integer terms, String contact, List<String> aliases,
            boolean clashing, String origin, List<PersonRetirement> retirements, List<String> tags) {
        this(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin,
                retirements, tags, List.of(new PersonTerms(terms, null)));
    }

    public Person(long id, String sheetId, String name, String grade, long version, String retiredFrom, boolean held,
            List<PersonGrade> grades, List<PersonHold> holds, Integer terms, String contact, List<String> aliases,
            boolean clashing, String origin, List<PersonRetirement> retirements) {
        this(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin,
                retirements, List.of());
    }

    public Person(long id, String sheetId, String name, String grade, long version, String retiredFrom, boolean held,
            List<PersonGrade> grades, List<PersonHold> holds, Integer terms, String contact, List<String> aliases) {
        this(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, false, null,
                List.of());
    }

    public Person(long id, String sheetId, String name, String grade, long version, String retiredFrom,
            List<PersonGrade> grades, List<PersonHold> holds, Integer terms, String contact, List<String> aliases) {
        this(id, sheetId, name, grade, version, retiredFrom, !holds.isEmpty(), grades, holds, terms, contact, aliases);
    }

    public Person(long id, String sheetId, String name, String grade, long version, String retiredFrom,
            List<PersonGrade> grades, List<PersonHold> holds, Integer terms, String contact) {
        this(id, sheetId, name, grade, version, retiredFrom, grades, holds, terms, contact, List.of());
    }

    /** The person with whether they clash in the sheet's tree. */
    public Person withClashing(boolean clashing) {
        return new Person(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin, retirements, tags, ownTerms, flag);
    }

    /** The person with the sheet they were transferred from (null: none). */
    public Person withOrigin(String origin) {
        return new Person(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin, retirements, tags, ownTerms, flag);
    }

    /** The person with their past retirements. */
    public Person withRetirements(List<PersonRetirement> retirements) {
        return new Person(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin, retirements, tags, ownTerms, flag);
    }

    /** The person with their tags. */
    public Person withTags(List<String> tags) {
        return new Person(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin, retirements, tags, ownTerms, flag);
    }

    /** The person with their own terms as recorded, and {@code terms} those in force on the sheet's today. */
    public Person withOwnTerms(List<PersonTerms> ownTerms, Integer terms) {
        return new Person(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin, retirements, tags, ownTerms, flag);
    }

    /** The person with their flag (null: never flagged). */
    public Person withFlag(PersonFlag flag) {
        return new Person(id, sheetId, name, grade, version, retiredFrom, held, grades, holds, terms, contact, aliases, clashing, origin, retirements, tags, ownTerms, flag);
    }

    /** Whether the person's flag is in force on the date: it is on or before the flag's until-date. */
    public boolean flaggedOn(LocalDate date) {
        return flag != null && flag.inForceOn(date);
    }

    /** The person's own terms from the beginning of time (null: none). */
    public Integer baseTerms() {
        return ownTerms.stream().filter((t) -> t.from() == null).findFirst().map(PersonTerms::days).orElse(null);
    }

    /** The person's own terms in force on a date (null: none, so their grade's or the sheet's). */
    public Integer termsOn(LocalDate date) {
        return termsOn(ownTerms, date);
    }

    /** The own terms in force on a date among these: the ones with the latest from-date on or before it (a null from-date
     *  is the beginning of time); null when there are none. */
    public static Integer termsOn(List<PersonTerms> terms, LocalDate date) {
        PersonTerms found = null;
        for (PersonTerms t : terms) {
            if (t.from() != null && t.from().isAfter(date)) {
                continue;
            }
            if (found == null || found.from() == null || (t.from() != null && t.from().isAfter(found.from()))) {
                found = t;
            }
        }
        return found == null ? null : found.days();
    }

    /** The person not retired, the retirement ended on the date kept among their past ones. */
    public Person unretired(LocalDate on) {
        List<PersonRetirement> past = new java.util.ArrayList<>(retirements);
        past.add(new PersonRetirement(LocalDate.parse(retiredFrom), on));
        return new Person(id, sheetId, name, grade, version, null, held, grades, holds, terms, contact, aliases, clashing, origin, List.copyOf(past), tags, ownTerms);
    }

    /** Whether the person's name or any alias is among the name keys (lower-cased names and aliases). */
    public boolean usesAny(java.util.Set<String> keys) {
        return keys.contains(PersonRepository.key(name)) || aliases.stream().anyMatch((a) -> keys.contains(PersonRepository.key(a)));
    }

    /** Whether a hold of the person covers the date. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch((h) -> h.covers(date));
    }

    /** Whether the person's retirement date is reached on the day: it is on or before it. From then on their OPEN or
     *  PENDING claims not bound by a statement count in no live total, as a hold's would. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && !LocalDate.parse(retiredFrom).isAfter(date);
    }

    public boolean retired() {
        return retiredFrom != null;
    }

    /** Whether a claim of the person may be dated {@code date}: not after their retirement date, nor after the from and
     *  before the to of a past retirement. */
    public boolean mayClaimOn(java.time.LocalDate date) {
        return (retiredFrom == null || !date.isAfter(java.time.LocalDate.parse(retiredFrom)))
                && retirements.stream().noneMatch((r) -> r.excludes(date));
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /** The grade in force on a date among these, by from-date; null when there are none. */
    public static String gradeOn(List<PersonGrade> grades, LocalDate date) {
        PersonGrade found = null;
        for (PersonGrade g : grades) {
            if (g.from() != null && g.from().isAfter(date)) {
                continue;
            }
            if (found == null || found.from() == null || (g.from() != null && g.from().isAfter(found.from()))) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
