import { isOpen, type Claim } from '../claims/claims';

/** What the late charge on a sheet depends on: its today (yyyy-MM-dd, '' while it loads), its
 *  late percent in force on a date (two decimals; a claim's charge takes the one in force on each of its 30-day boundaries) and its policy date (yyyy-MM-dd; its today while blank): a claim whose `roundsOn` is
 *  before it rounds its live figures half up, one on or after it half to even; and a claim's grace in days (that of its
 *  person's grade in force on its date, in force on that date; 0 when none); and the rounding mode in force on a date
 *  (half-up or half-even; null when none), which, when a claim's `roundsOn` has one, decides how it rounds instead. */
export type Late = {
  today: string; pct: (date: string) => string; policy: string; grace: (claim: Claim) => number;
  rounding: (date: string) => string | null;
};

/** Whether the claim's live figures round half up (by the rounding mode in force on its `roundsOn`, else when it rounds
 *  on a date before the policy date) rather than half to even. */
export function roundsHalfUp(claim: Claim, late: Late | undefined): boolean {
  if (late === undefined) return false;
  const mode = late.rounding(claim.roundsOn);
  if (mode === 'half-up') return true;
  if (mode === 'half-even') return false;
  return late.policy !== '' && claim.roundsOn < late.policy;
}

/** Days since 1970-01-01 of a yyyy-MM-dd date. */
export function day(date: string): number {
  const [y, m, d] = date.split('-').map(Number);
  return Date.UTC(y, m - 1, d) / 86_400_000;
}

/** A claim's due-by (yyyy-MM-dd): fixed when it was added, the terms-th business day after its date (skipping weekends and the sheet's holidays then), by its person's own terms then, else those of their grade. */
export function dueBy(claim: Claim): string {
  return claim.dueBy;
}

/** The date a claim is late from (yyyy-MM-dd): its due-by plus its grace (see Late). */
export function lateFrom(claim: Claim, late: Late): string {
  const grace = late.grace(claim);
  return grace === 0 ? dueBy(claim) : plusDays(dueBy(claim), grace);
}

/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its due-by plus its grace is before the sheet's today. */
export function isOverdue(claim: Claim, late: Late): boolean {
  return isOpen(claim) && !claim.deferred && late.today !== '' && lateFrom(claim, late) < late.today;
}

/** How many full 30 days an overdue claim is overdue (0 when it is not overdue, its due is fixed by settling, or it is a
 *  correction, which bears no late charge, or its late charge is waived). */
export function lateSteps(claim: Claim, late: Late): number {
  if (claim.waived || claim.due !== null || claim.amount.trim().startsWith('-') || !isOverdue(claim, late)) return 0;
  return Math.floor((day(late.today) - day(lateFrom(claim, late))) / 30);
}

/** A yyyy-MM-dd date the given days after another. */
export function plusDays(date: string, days: number): string {
  return new Date((day(date) + days) * 86_400_000).toISOString().slice(0, 10);
}

/** Whether a REVIEW claim is review-late: its review day (the sheet's today on the latest REVIEW line of its status log)
 *  plus the review SLA days is before the sheet's today (never with no SLA, or for a claim not in REVIEW). */
export function isReviewLate(claim: Claim, sla: number | null, today: string): boolean {
  if (claim.status !== 'REVIEW' || sla === null || today === '') return false;
  const reviewed = [...claim.log].reverse().find((l) => l.status === 'REVIEW');
  return reviewed !== undefined && plusDays(reviewed.date, sla) < today;
}

/** Whether a PENDING claim is pending-late: its pending day (the sheet's today on the latest PENDING line of its status log)
 *  plus the pending SLA days is before the sheet's today (never with no SLA, or for a claim not PENDING). */
export function isPendingLate(claim: Claim, sla: number | null, today: string): boolean {
  if (claim.status !== 'PENDING' || sla === null || today === '') return false;
  const pending = [...claim.log].reverse().find((l) => l.status === 'PENDING');
  return pending !== undefined && plusDays(pending.date, sla) < today;
}

/** The 30-day boundaries an overdue claim has passed (its due-by plus its grace plus 30, 60, 90 ... days, on or before today), each
 *  bearing the late percent in force on it; none when it bears no late charge (see lateSteps). */
export function lateBoundaries(claim: Claim, late: Late): string[] {
  const steps = lateSteps(claim, late);
  return Array.from({ length: steps }, (_, i) => plusDays(lateFrom(claim, late), 30 * (i + 1)));
}
import type { Claim } from '../claims/claims';
import { gradeOn, type Person } from '../people/people';
import { claimDue, claimRate, sum, type Rate } from '../rates/rates';
import type { Dated } from '../settings/settings';
import { isOverdue, type Late } from './late';

export { dueBy, isOverdue } from './late';

/** The overdue count and overdue-total (their dues, late charge included, added up, skipping n/a) of the given
 *  claims that count. */
export function overdue(
  claims: Claim[],
  rates: Rate[] | undefined,
  person: Person,
  late: Late,
  floor: Dated,
): { count: number; total: string } {
  const over = claims.filter((c) => isOverdue(c, late));
  return { count: over.length, total: sum(over.map((c) => claimDue(c, claimRate(rates, gradeOn(person, c.date), c), floor, late))) };
}
/** A person's score from their settled figures (two decimals, see personSplit) and their overdue count: the settled
 *  figures / 100, minus 5 for every overdue claim, rounded once, half to even, to a whole number. */
export function score(settled: string, overdueCount: number): string {
  const [whole, frac = ''] = settled.replace('-', '').split('.');
  const h = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0').slice(0, 2));
  const p = (settled.startsWith('-') ? -h : h) - 50000n * BigInt(overdueCount); // in 1/10000 of the score
  const a = p < 0n ? -p : p;
  const q = a / 10000n;
  const rem = a % 10000n;
  const r = rem > 5000n || (rem === 5000n && q % 2n === 1n) ? q + 1n : q;
  return String(p < 0n ? -r : r);
}

/** A person's band from their score (see score) and the sheet's score thresholds: HIGH at or above the high one, MID at
 *  or above the mid one, else LOW; empty while either threshold is blank. */
export function band(score: string, mid: string | null, high: string | null): string {
  if (mid === null || high === null) return '';
  const s = BigInt(score);
  return s >= BigInt(high) ? 'HIGH' : s >= BigInt(mid) ? 'MID' : 'LOW';
}
import { SheetPage } from '../../slots/defs/sheetPage';
import { isActive } from '../active/active';
import { useClaims } from '../claims/claims';
import { STATUSES, useGradeDue, useStatusCounts } from '../header/totals';
import { gradeOn, usePeople } from '../people/people';
import { useGradeCodes } from '../grades/grades';
import { periodDue, usePeriods } from '../periods/periods';
import { difference, useRates } from '../rates/rates';
import { isPendingLate, isReviewLate } from '../overdue/late';
import { useFloor, useLate, usePendingSla, useReviewSla } from '../settings/settings';
import { useVoidReasons } from '../voidreasons/voidreasons';

/** The sheet's summary, worked out from the same figures the lists show. Per grade: the people on it on the sheet's
 *  today (retired people excluded), their due-totals added up (skipping n/a) and how many of them are active. Per period: its due-total, and its
 *  change from the period before it by start date (blank for the earliest). Per
 *  status: how many of the sheet's claims have it, and how many REVIEW claims are review-late (see isReviewLate), and how many PENDING claims are pending-late (see isPendingLate). Per void reason on the sheet's list: how many VOID claims were voided
 *  with it. */
function Summary({ sheetId }: { sheetId: string }) {
  const gradeCodes = useGradeCodes(sheetId);
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const periods = usePeriods(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const reviewSla = useReviewSla(sheetId);
  const pendingSla = usePendingSla(sheetId);

  const active = (people.data ?? []).filter((p) => p.retiredFrom === null);
  const onGrade = (grade: string) => active.filter((p) => gradeOn(p, late.today) === grade);
  const gradeDue = useGradeDue(sheetId);
  const byStart = [...(periods.data ?? [])].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0));
  const dueOf = new Map(byStart.map((p) => [p.id, periodDue(p, claims.data, people.data, rates.data, floor, late)]));
  const changeOf = new Map(
    byStart.map((p, i) => [p.id, i === 0 ? '' : difference(dueOf.get(p.id)!, dueOf.get(byStart[i - 1].id)!)]),
  );
  const withStatus = useStatusCounts(sheetId);
  const voidReasons = useVoidReasons(sheetId);

  return (
    <section data-testid="summary">
      <h3>Summary</h3>
      <table data-testid="summary-grades">
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {gradeCodes.map((g) => (
            <tr key={g}>
              <td>{g}</td>
              <td data-testid={`summary-grade-${g}-count`}>{onGrade(g).length}</td>
              <td data-testid={`summary-grade-${g}-due-total`}>{gradeDue(g)}</td>
              <td data-testid={`summary-grade-${g}-active`}>
                {onGrade(g).filter((p) => isActive(p, claims.data, late.today)).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-periods">
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.id}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>
                {dueOf.get(p.id)}
              </td>
              <td data-testid={`summary-period-${p.name}-change`}>{changeOf.get(p.id)}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table data-testid="summary-statuses">
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{withStatus(s)}</td>
            </tr>
          ))}
          <tr>
            <td>Review late</td>
            <td data-testid="summary-review-late-count">
              {(claims.data ?? []).filter((c) => isReviewLate(c, reviewSla, late.today)).length}
            </td>
          </tr>
          <tr>
            <td>Pending late</td>
            <td data-testid="summary-pending-late-count">
              {(claims.data ?? []).filter((c) => isPendingLate(c, pendingSla, late.today)).length}
            </td>
          </tr>
        </tbody>
      </table>
      <table data-testid="summary-void-reasons">
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {(voidReasons.data ?? []).map((r) => (
            <tr key={r.reason}>
              <td>{r.reason}</td>
              <td data-testid={`summary-void-${r.reason}-count`}>{r.count}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 40, Component: Summary });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { nowKey, useReadNow } from '../../query/readNow';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade a person has from a date (yyyy-MM-dd) until their next one's; a null `from` applies from the beginning of
 *  time (the first grade the person was given). */
export type PersonGrade = { grade: string; from: string | null };

/** A person on the sheet. `name` is unique on the sheet (case ignored), kept without outer spaces; `grades` are the
 *  grades recorded, by from-date, and `grade` (A, B or C) the one in force on the sheet's today.
 *  `version` goes up by one on each stored edit; an edit sends the version it was made from. `retiredFrom` (yyyy-MM-dd)
 *  is the date the person is retired from, null when not retired: a person with one counts as retired at once. `holds` are
 *  the person's holds, by from-date: a claim of theirs dated within one still counts in every total; a hold
 *  only takes the person's cut in the pools. `held` is whether they have any hold. `terms` are the person's own terms in days (ahead of
 *  their grade's and the sheet's when a claim is added) in force on the sheet's today, null when they have none;
 *  `ownTerms` are their own terms as recorded, by from-date (null: from the beginning of time), a claim having those in
 *  force on its date. `contact` is the person's contact
 *  (unique on the sheet; without surrounding spaces, lower-cased), null when none. `aliases` are the person's aliases,
 *  sorted as names are compared: no alias equals (case ignored) any name or alias on the sheet, and the quick-add bar and
 *  the paste box find a person by one as by the name. `clashing` is whether their name or an alias is used as a name or
 *  alias on another sheet of the sheet's tree (people added before the rule): every edit of them is refused until it
 *  renames them clear. `origin` is the sheet they were last transferred from, null when never transferred here.
 *  `retirements` are their past retirements (each ended by unretiring them), in the order they ended.
 *  `tags` are the person's tags (each trimmed and in lower case, no repeats, sorted; empty when none): a claim of theirs
 *  counts for each in the tag totals. */
/** A person's own terms in days (null: none) from a date (yyyy-MM-dd; null: the beginning of time). */
export type PersonTerms = { days: number | null; from: string | null };

export type Person = {
  id: number;
  sheetId: string;
  name: string;
  grade: string;
  version: number;
  retiredFrom: string | null;
  held: boolean;
  grades: PersonGrade[];
  holds: PersonHold[];
  terms: number | null;
  ownTerms: PersonTerms[];
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  retirements: PersonRetirement[];
  tags: string[];
  flag: PersonFlag | null;
};

/** A steward's flag on a person: its reason, in force until its until-date (yyyy-MM-dd, included). While the sheet's
 *  today is on or before it only a steward may open a claim of the person; after it the flag shows nothing. */
export type PersonFlag = { reason: string; until: string };

/** The reason of the person's flag in force on the day (yyyy-MM-dd), or '' when none is. */
export const flagOn = (person: Pick<Person, 'flag'>, on: string) =>
  person.flag && on !== '' && on <= person.flag.until ? person.flag.reason : '';

/** A past retirement of a person (yyyy-MM-dd): from their retirement date to the sheet's today when they were
 *  unretired. No claim of theirs may be dated after the from and before the to. */
export type PersonRetirement = { from: string; to: string };

/** A hold on a person from a date until a date (yyyy-MM-dd, both included); a null `to` is open-ended. */
export type PersonHold = { from: string; to: string | null };

/** Whether a hold of the person covers the date (yyyy-MM-dd). */
export const heldOn = (person: Pick<Person, 'holds'>, on: string) =>
  (person.holds ?? []).some((h) => h.from <= on && (h.to === null || on <= h.to));

/** Whether the person's retirement date is reached on the day (yyyy-MM-dd): it is on or before it. From then on their
 *  open (OPEN or PENDING) claims not bound by a statement count in no live total. */
export const retiredOn = (person: Pick<Person, 'retiredFrom'>, on: string) =>
  person.retiredFrom !== null && on !== '' && person.retiredFrom <= on;

/** The person's grade in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Pick<Person, 'grade' | 'grades'>, on: string): string {
  let found: PersonGrade | undefined;
  for (const g of person.grades ?? []) {
    if (g.from !== null && g.from > on) continue;
    if (found === undefined || found.from === null || (g.from !== null && g.from > found.from)) found = g;
  }
  return found?.grade ?? person.grade;
}

/** How the screen shows a person's name: `<name> (<grade in force on the sheet's today>)`. Exports, audit lines, the
 *  import and paste boxes and the selects of names keep the plain name. */
export const shownName = (person: Pick<Person, 'name' | 'grade'>) => `${person.name} (${person.grade})`;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'];

/** The sheet's people, in list order (new people at the end; see the move buttons). */
export function usePeople(sheetId: string) {
  const now = useReadNow();
  return useQuery({
    queryKey: nowKey(peopleKey(sheetId), now),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`, now),
  });
}

/** The id of the person whose editor is open (in the person form), or '' when the form adds. */
export const useEditingPerson = () => useSearchParam('person', asString);

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet leaves it as it is. */
export const useShowRetired = () => useSearchParam('retired', asFlag);

/** What the people list is sorted by on this screen: list order (added), name (as names are compared: case ignored),
 *  grade, or due-total (n/a last). Equal keys keep list order. Only the screen's order changes: every action in list
 *  order, and the rollups, still go by list order. */
export const SORT_KEYS = ['added', 'name', 'grade', 'due-total'] as const;
export const useSortBy = () => useSearchParam('sort', asString);

/** The people in the order the sort key gives; `due` is each person's due-total (two decimals, or n/a) by id. */
export function sortPeople(people: Person[], key: string, due: Map<number, string>): Person[] {
  const nameKey = (p: Person) => p.name.toLowerCase();
  const dueKey = (p: Person) => {
    const d = due.get(p.id);
    return d === undefined || d === 'n/a' ? Infinity : Number(d);
  };
  const cmp: ((a: Person, b: Person) => number) | undefined =
    key === 'name'
      ? (a, b) => (nameKey(a) < nameKey(b) ? -1 : nameKey(a) > nameKey(b) ? 1 : 0)
      : key === 'grade'
        ? (a, b) => (a.grade < b.grade ? -1 : a.grade > b.grade ? 1 : 0)
        : key === 'due-total'
          ? (a, b) => (dueKey(a) === dueKey(b) ? 0 : dueKey(a) < dueKey(b) ? -1 : 1)
          : undefined;
