  grades: PersonGrade[];
  holds: PersonHold[];
  terms: number | null;
  ownTerms: PersonTerms[];
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  retirements: PersonRetirement[];
  tags: string[];
  flag: PersonFlag | null;
};

/** A steward's flag on a person: its reason, in force until its until-date (yyyy-MM-dd, included). While the sheet's
 *  today is on or before it only a steward may open a claim of the person; after it the flag shows nothing. */
export type PersonFlag = { reason: string; until: string };

/** The reason of the person's flag in force on the day (yyyy-MM-dd), or '' when none is. */
export const flagOn = (person: Pick<Person, 'flag'>, on: string) =>
  person.flag && on !== '' && on <= person.flag.until ? person.flag.reason : '';

/** A past retirement of a person (yyyy-MM-dd): from their retirement date to the sheet's today when they were
 *  unretired. No claim of theirs may be dated after the from and before the to. */
export type PersonRetirement = { from: string; to: string };

/** A hold on a person from a date until a date (yyyy-MM-dd, both included); a null `to` is open-ended. */
export type PersonHold = { from: string; to: string | null };

/** Whether a hold of the person covers the date (yyyy-MM-dd). */
export const heldOn = (person: Pick<Person, 'holds'>, on: string) =>
  (person.holds ?? []).some((h) => h.from <= on && (h.to === null || on <= h.to));

/** Whether the person's retirement date is reached on the day (yyyy-MM-dd): it is on or before it. From then on their
 *  open (OPEN or PENDING) claims not bound by a statement count in no live total. */
export const retiredOn = (person: Pick<Person, 'retiredFrom'>, on: string) =>
  person.retiredFrom !== null && on !== '' && person.retiredFrom <= on;

/** The person's grade in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Pick<Person, 'grade' | 'grades'>, on: string): string {
  let found: PersonGrade | undefined;
  for (const g of person.grades ?? []) {
    if (g.from !== null && g.from > on) continue;
    if (found === undefined || found.from === null || (g.from !== null && g.from > found.from)) found = g;
  }
  return found?.grade ?? person.grade;
}

/** How the screen shows a person's name: `<name> (<grade in force on the sheet's today>)`. Exports, audit lines, the
 *  import and paste boxes and the selects of names keep the plain name. */
export const shownName = (person: Pick<Person, 'name' | 'grade'>) => `${person.name} (${person.grade})`;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'];

/** The sheet's people, in list order (new people at the end; see the move buttons). */
export function usePeople(sheetId: string) {
  const now = useReadNow();
  return useQuery({
    queryKey: nowKey(peopleKey(sheetId), now),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`, now),
  });
}

/** The id of the person whose editor is open (in the person form), or '' when the form adds. */
export const useEditingPerson = () => useSearchParam('person', asString);

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet leaves it as it is. */
export const useShowRetired = () => useSearchParam('retired', asFlag);

/** What the people list is sorted by on this screen: list order (added), name (as names are compared: case ignored),
 *  grade, or due-total (n/a last). Equal keys keep list order. Only the screen's order changes: every action in list
 *  order, and the rollups, still go by list order. */
export const SORT_KEYS = ['added', 'name', 'grade', 'due-total'] as const;
export const useSortBy = () => useSearchParam('sort', asString);

/** The people in the order the sort key gives; `due` is each person's due-total (two decimals, or n/a) by id. */
export function sortPeople(people: Person[], key: string, due: Map<number, string>): Person[] {
  const nameKey = (p: Person) => p.name.toLowerCase();
  const dueKey = (p: Person) => {
    const d = due.get(p.id);
    return d === undefined || d === 'n/a' ? Infinity : Number(d);
  };
  const cmp: ((a: Person, b: Person) => number) | undefined =
    key === 'name'
      ? (a, b) => (nameKey(a) < nameKey(b) ? -1 : nameKey(a) > nameKey(b) ? 1 : 0)
      : key === 'grade'
        ? (a, b) => (a.grade < b.grade ? -1 : a.grade > b.grade ? 1 : 0)
        : key === 'due-total'
          ? (a, b) => (dueKey(a) === dueKey(b) ? 0 : dueKey(a) < dueKey(b) ? -1 : 1)
          : undefined;
  return cmp === undefined ? people : [...people].sort(cmp); // Array.sort is stable: equal keys keep list order
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { nowKey, useReadNow } from '../../query/readNow';
import { retiredOn, type Person } from '../people/people';

/** A claim's status: DRAFT when added, then OPEN and SETTLED; a clerk settling above the clerk limit makes it PENDING
 *  until a steward approves (SETTLED) or rejects (OPEN) it; a DRAFT, OPEN or PENDING claim may be VOID, as may a SETTLED one
 *  by a steward within 7 days of its settlement; a DRAFT may be DELETED (counting nowhere), and restored to DRAFT on the
 *  sheet-today it was deleted. Opening a claim whose due is above the review threshold on its date makes it REVIEW
 *  (unnumbered, counting nowhere) until a steward reviews it (OPEN); it may only be voided otherwise. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';

/** A claim of a person. `amount` is text with two decimals (never a float); `date` is yyyy-MM-dd; `number` (text: FY2026-1, FY2026-2, ... (older claims 1, 2, ...), or P1-1, X-1 when numbered per period) is given
 *  when the claim is opened (null for a draft or a voided claim); `due` is the due fixed when it was settled (null
 *  while its due is live, worked out from its grade's current rate); `openedBy` is who opened it (null when never
 *  opened); `stated` is whether its person's last statement bound it to the due as shown, late charge included, `statedDue` (null when it had
 *  none), which it shows while its due is not fixed; `corrects` is, for a correction (a negative amount),
 *  the number of the SETTLED claim of the same person it corrects (null for any other claim); `roundsOn` (yyyy-MM-dd)
 *  is the date that decides how its live figures round: the corrected claim's date for a correction, else its own;
 *  `dueBy` (yyyy-MM-dd) is its due-by, fixed when it was added from the terms in force on that day (its person's own, else their grade's, else the sheet's), or as a steward last set it directly (then kept, whatever holiday is added later);
 *  `deferred` is whether it is deferred on the sheet's today (a claim that counts, deferred until a date after it and
 *  not bound by a statement: it counts in no total, is not overdue and cannot be settled; while bound the deferral
 *  waits for the binding to end) and `deferredUntil` (yyyy-MM-dd) the date it was last deferred until (shown
 *  even once that date has passed; null when never deferred); `proofs` is its proofs count (a claim whose due is above the sheet's proof threshold
 *  on its date cannot be settled nor approved while it is 0); `splitFrom` is the number of the claim it was split from
 *  (null for any other claim); `log` is its status log, oldest first; `lockedBy` is who has its editor open (it is locked for
 *  everyone else; null when no one does). */
export type Claim = {
  id: number;
  sheetId: string;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  dueBy: string;
  deferred: boolean;
  deferredUntil: string | null;
  /** Whether a steward waived its late charge: from then on it bears none, whatever its overdue state. */
  waived: boolean;
  /** The user a steward last assigned it to for review (null when never): kept once it leaves REVIEW. */
  reviewAssigned: string | null;
  /** Whether it is held (an OPEN or PENDING claim is held and released with Hold): a held claim still counts in every
   *  total, as one dated within a hold of its person does. */
  held: boolean;
  proofs: number;
  /** How many of its proofs are receipts (the kind when none is chosen) and photos. */
  proofsReceipt: number;
  proofsPhoto: number;
  splitFrom: string | null;
  log: ClaimLogLine[];
  lockedBy: string | null;
  /** Whether it was added while the period its date falls in was soft-closed. */
  lateEntry: boolean;
  /** The last day (yyyy-MM-dd) a reminder was written for it; null when never reminded. */
  reminded: string | null;
  /** Its external reference (surrounding spaces removed; no two claims of a sheet share one, case ignored); null when none. */
  ref: string | null;
  /** Its tags: each trimmed and in lower case, no repeats, sorted; empty when none. */
  tags: string[];
  /** Its comments, in the order written. */
  comments: ClaimComment[];
  /** The number of the bulk settle batch that settled it; null when none did (settled one at a time, or not settled). */
  batch: number | null;
  /** Its lines, in the order added; with any, its amount is their quantities times unit amounts added up. */
  lines: ClaimLine[];
  /** The order it was added in, across every sheet: a forward-only rate applies only to claims whose seq is above its
   *  `after` (see claimRate); absent for a claim not yet added. */
  seq?: number;
  /** The shares of it other people of the sheet hold, in the order made: each holder's person id and share (a percent,
   *  two decimals). Each holder's part of its due counts in their figures instead of its own person's (see shareParts). */
  shares?: ClaimShare[];
};

/** A share of a claim: its holder's person id and their share (a percent, two decimals). */
export type ClaimShare = { personId: number; share: string };

/** A line of a claim: its label, quantity (a whole number, at least 1) and unit amount (two decimals). */
export type ClaimLine = { label: string; qty: number; unit: string };

/** A line as shown: `<label> <qty> x <unit>`. */
export const lineLine = (l: ClaimLine) => `${l.label} ${l.qty} x ${l.unit}`;

/** A comment on a claim: who wrote it, the sheet's today (yyyy-MM-dd) when it was written, and its text. */
export type ClaimComment = { by: string; date: string; text: string };

/** A comment as shown: `<user> on <date>: <text>`. */
export const commentLine = (m: ClaimComment) => `${m.by} on ${m.date}: ${m.text}`;

/** One line of a claim's status log: the status it took, who made the change, the sheet's today (yyyy-MM-dd) when
 *  it was made, and the claim's due as shown at that moment (two decimals, or n/a). */
export type ClaimLogLine = { status: ClaimStatus; by: string; date: string; due: string };

/** A status log line as shown: `<STATUS> by <user> on <date> due=<due>`. */
export const logLine = (l: ClaimLogLine) => `${l.status} by ${l.by} on ${l.date} due=${l.due}`;

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'];

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  const now = useReadNow();
  return useQuery({
    queryKey: nowKey(claimsKey(sheetId), now),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`, now),
  });
}

/** An amount ("12.34") in whole cents, so sums are exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do, and no deferred one. */
export const counts = (c: Claim) => (isOpen(c) || c.status === 'SETTLED') && !c.deferred;

/** Whether a statement binds the claim now: it is stated (PENDING included). */
export const bound = (c: Claim) => c.stated;

/** The claims that count in the live totals (claimed, due-totals, a period's due-total): a person's open (OPEN or
 *  PENDING) claims once their retirement date is reached on the sheet's today (yyyy-MM-dd), and not bound by a statement,
 *  do not; their other claims still do. A hold (the claim's or its person's) takes no claim out. */
export function live(claims: Claim[], people: Person[] | undefined, today: string): Claim[] {
  const byId = new Map((people ?? []).map((p) => [p.id, p]));
  return claims.filter((c) => {
    const p = byId.get(c.personId);
    return counts(c) && !(isOpen(c) && !bound(c) && p !== undefined && retiredOn(p, today));
  });
}

/** The claims that count toward claimed (a person's claimed, the claimed-total): the same claims as live. */
export function liveClaimed(claims: Claim[], people: Person[] | undefined, today: string): Claim[] {
  const byId = new Map((people ?? []).map((p) => [p.id, p]));
  return claims.filter((c) => {
    const p = byId.get(c.personId);
    return counts(c) && !(isOpen(c) && !bound(c) && p !== undefined && retiredOn(p, today));
  });
}

/** A person's or the sheet's claimed: the amounts of the claims that count added up, leaving out corrections
 *  (claims that correct another), shown with two decimals. */
export function claimed(claims: Claim[]): string {
  return total(claims.filter((c) => !c.corrects));
}

/** The amounts of the claims that count added up, shown with two decimals. */
export function total(claims: Claim[]): string {
  return (claims.filter(counts).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}

