/** Whether a person is active on the sheet's today (yyyy-MM-dd): they have an open (OPEN or PENDING) claim that
 *  counts in the live totals, dated within the 30 days up to and including today. */
export function isActive(person: Person, claims: Claim[] | undefined, today: string): boolean {
  if (today === '') return false;
  const since = plusDays(today, -29);
  return live(claims?.filter((c) => c.personId === person.id) ?? [], [person], today).some(
    (c) => isOpen(c) && c.date >= since && c.date <= today,
  );
}

function OverdueHead({ user }: { user: string }) {
  const shown = useShownColumns(user);
  return (
    <>
      {shown('overdue-count') && <th>Overdue</th>}
      {shown('overdue-total') && <th>Overdue total</th>}
    </>
  );
}

/** A person's overdue count and overdue-total, over their claims that count in the live totals. */
function PersonOverdue({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const shown = useShownColumns(user);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const mine = live(claims.data?.filter((c) => c.personId === person.id) ?? [], [person], late.today);
  const o = overdue(mine, rates.data, person, late, floor);
  return (
    <>
      {shown('overdue-count') && <td data-testid="person-overdue-count">{o.count}</td>}
      {shown('overdue-total') && <td data-testid="person-overdue-total">{o.total}</td>}
    </>
  );
}

/** The sheet's overdue count and overdue-total: everyone's added up. */
function OverdueTotal({ sheetId }: { sheetId: string }) {
  const all = useSheetOverdue(sheetId);
  return (
    <p>
      Overdue <span data-testid="rollup-overdue-count">{all.count}</span>, total{' '}
      <span data-testid="rollup-overdue-total">{all.total}</span>
    </p>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 25, Component: OverdueHead }),
  PersonRow.fill({ order: 25, Component: PersonOverdue }),
  SheetPage.fill({ order: 35, Component: OverdueTotal }),
];

function ScoreHead() {
  return (
    <>
      <th>Score</th>
      <th>Band</th>
    </>
  );
}

/** A person's score (see score), and their band by it (see band), over their claims that count in the live totals; its
 *  settled figures leave out corrections. */
function PersonScore({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const mine = live(claims.data?.filter((c) => c.personId === person.id) ?? [], [person], late.today);
  const settled = personSplit(mine.filter((c) => !c.corrects), rates.data, person, late, floor).settled;
  const count = overdue(mine, rates.data, person, late, floor).count;
  const thresholds = useScoreThresholds(sheetId);
  const shown = score(settled, count);
  return (
    <>
      <td data-testid="person-score">{shown}</td>
      <td data-testid="person-band">{band(shown, thresholds.mid, thresholds.high)}</td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 26, Component: ScoreHead }),
  PersonRow.fill({ order: 26, Component: PersonScore }),
];

