package net.officefloor.hq.app.claim;


/** Applies the edited values; only a DRAFT claim can be edited (an open claim is voided and a new one added instead),
 * and a claim whose due-by (which an edit leaves as it is) falls inside a closed period, or left or moved after its person's retirement date,
 * is refused, as is another amount than its lines' total for a claim with lines, and a reference another claim of the sheet already has (see ClaimRules.checkRef). */
public class ApplyClaim {
    public void apply(@Val Claim claim, @Val ClaimValues values, SheetRepository sheets, PeriodRepository periods,
            PersonRepository people, ClaimRepository claims, Out<Claim> changed) throws InvalidClaimException {
        if (claim.status() != ClaimStatus.DRAFT) {
            throw new InvalidClaimException("Only a DRAFT claim can be edited");
        }
        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.sheetId());
        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
            throw new InvalidClaimException("The claim's due-by is inside a closed period");
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person != null && !person.mayClaimOn(date)) {
            throw new InvalidClaimException("The claim's date is after the person's retirement date");
        }
        if (values.amount().compareTo(claim.amount()) != 0 && claims.hasLines(claim.sheetId(), claim.id())) {
            throw new InvalidClaimException("A claim with lines takes its amount from them");
        }
        ClaimRules.checkRef(claim.sheetId(), values, claim.id(), claims);
        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), values.amount(), date, values.note(), claim.status(),
                claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(),
                Corrections.check(claim.sheetId(), claim.personId(), values, claim.id(), claims), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), values.ref(), values.tags(), claim.held()));
    }
}
package net.officefloor.hq.app.claim;


/**
 * The number a claim receives as it is settled or approved (see SaveClaimStatus). While the sheet's period-numbering-from setting is a date and the
 * sheet's today is on or after it, the claim is numbered within the period containing its due-by, {@code <period>-<n>}
 * counting from 1 in each period, or {@code X-<n>} in its own sequence when no period contains it. Otherwise it takes
 * the next number of the sheet's tree within the fiscal year of its due-by (by the sheet's fiscal start month),
 * {@code FY<yyyy>-<n>}: one more than the last number given in that fiscal year on any sheet of the tree, counting from
 * 1 in each fiscal year, so the sheets of a tree share one sequence per fiscal year.
 */
public final class ClaimNumbering {

    private ClaimNumbering() {
    }

    public static String next(Claim claim, ClaimRepository claims, PeriodRepository periods, SettingRepository settings,
            SheetRepository sheets) {
        String sheet = claim.sheetId();
        if (!perPeriod(sheet, settings, sheets)) {
            String fy = fiscalYearOf(claim.dueBy(), settings.fiscalStartMonth(sheet));
            return fy + "-" + claims.nextFiscalYearNumber(sheet, settings.tree(sheet), fy);
        }
        Period period = periods.containing(sheet, claim.dueBy());
        String key = period == null ? "X" : period.name();
        return key + "-" + claims.nextPeriodNumber(sheet, key);
    }

    /** The fiscal year a date falls in, FY<yyyy> by the calendar year its first day (of the start month) falls in. */
    public static String fiscalYearOf(LocalDate date, int startMonth) {
        return "FY" + (date.getMonthValue() >= startMonth ? date.getYear() : date.getYear() - 1);
    }

    /** Whether claims are numbered per period now: the period-numbering-from setting is a date on or before today. */
    public static boolean perPeriod(String sheet, SettingRepository settings, SheetRepository sheets) {
        LocalDate from = settings.periodNumberingFrom(sheet);
        return from != null && !sheets.today(sheet).isBefore(from);
    }
}
package net.officefloor.hq.app.person;


/** Matches each imported line to the person on the sheet with its name or alias (as names are compared), and checks
 *  every line before any is stored: a matched line as the person form checks an edit (see CheckPersonRename and
 *  CheckPersonRecontact and CheckPersonRegrade), any other as it checks an add (see CheckNewPersonName,
 *  CheckNewPersonGrade and CheckPersonContact). Two lines
 *  matching the same person, or any failing line, refuse the whole import. */
public class CheckImportedPeople {
    public void check(@PathVariable("sheetId") String sheetId, @Val ImportedPeople imported, PersonRepository people,
            GradeRepository grades, Out<ImportMatches> matches)
            throws DuplicatePersonNameException, DuplicatePersonContactException, InvalidPersonException {
        String sheet = sheetId.trim();
        List<Person> matched = new ArrayList<>();
        Set<Long> seen = new HashSet<>();
        for (PersonValues values : imported.people()) {
            Person person = people.findByName(sheet, values.name());
            if (person == null) {
                if (people.nameTaken(sheet, values.name(), 0) || people.treeTaken(sheet, values.name())) {
                    throw new DuplicatePersonNameException(values.name());
                }
                grades.checkChoosable(sheet, values.grade());
                if (values.contact() != null && people.contactTaken(sheet, values.contact(), 0)) {
                    throw new DuplicatePersonContactException(values.contact());
                }
            } else {
                if (!seen.add(person.id())) {
                    throw new InvalidPersonException("The person " + person.name() + " is imported more than once");
                }
                PersonValues edit = AddImportedPeople.edit(person, values);
                new CheckPersonRename().check(person, edit, people);
                new CheckPersonRecontact().check(person, edit, people);
                CheckPersonRegrade.refuse(sheet, person, edit, grades);
            }
            matched.add(person);
        }
        matches.set(new ImportMatches(Collections.unmodifiableList(matched)));
    }
}
package net.officefloor.hq.app.person;


/** Stores the checked lines in the order pasted. A line matching a person updates them as the person form edits one:
 *  the grade recorded from the sheet's today (see ApplyPerson), the terms and contact set when the line gives them,
 *  written as PERSON_EDITED (see RecordPersonEdited). Any other adds a person as the form adds one, written as
 *  PERSON_ADDED (see RecordPersonAdded). Each then writes the figures it moved (see Rollup). */
public class AddImportedPeople {
    public void add(@PathVariable("sheetId") String sheetId, @Val ImportedPeople imported, @Val ImportMatches matches,
            PersonRepository people, SheetRepository sheets, Rollup rollup, Audit audit, Out<ImportPeopleResult> result)
            throws DuplicatePersonNameException, DuplicatePersonContactException, StalePersonException {
        String sheet = sheetId.trim();
        int added = 0;
        int updated = 0;
        for (int i = 0; i < imported.people().size(); i++) {
            PersonValues values = imported.people().get(i);
            Person matched = matches.people().get(i);
            RollupBefore before = rollup.take(sheet);
            if (matched == null) {
                Person person = people.add(sheet, values.name(), values.grade(), values.terms(), values.contact());
                new RecordPersonAdded().record(person, values, before, rollup, audit);
                added++;
            } else {
                PersonValues edit = edit(matched, values);
                Person person = ApplyPerson.edited(matched, edit, sheets.today(sheet));
                people.update(person, matched.version());
                new RecordPersonEdited().record(person, edit, new TermsBefore(matched.terms(), matched.ownTerms()),
                        new ContactBefore(matched.contact()), before, rollup, audit);
                updated++;
            }
        }
        result.set(new ImportPeopleResult(added, updated));
    }

    /** The edit a line makes to the person it matches: their name kept, the line's grade from the sheet's today, and
     *  the line's terms and contact where it gives them (else the person's own). */
    static PersonValues edit(Person person, PersonValues line) {
        return new PersonValues(person.name(), line.grade(), line.by(), person.version(), null,
                line.terms() != null ? line.terms() : person.terms(),
                line.contact() != null ? line.contact() : person.contact(), person.tags());
    }
}

